const t = $('Current Topic').first().json;
if ($json.error) {
  return { json: Object.assign({}, t, { sources: [], source_count: 0, rejected_sources: [], research_brief: '', retrieved_at: new Date().toISOString(), failure_kind: 'service_error', error_summary: 'Research provider error: ' + String($json.error.message || $json.error) }) };
}
const results = Array.isArray($json.results) ? $json.results : [];
const NL = String.fromCharCode(10);
const retrievedAt = new Date().toISOString();
const seen = new Set();
const valid = [];
const rejected = [];
function parseHost(raw) {
  const str = String(raw || '').trim();
  const lower = str.toLowerCase();
  if (!lower.startsWith('https://') && !lower.startsWith('http://')) return null;
  let host = str.slice(str.indexOf('://') + 3).split('/')[0].split('?')[0].split('#')[0];
  host = host.split('@').pop().split(':')[0].toLowerCase();
  if (!host || host.indexOf('.') === -1) return null;
  return host.startsWith('www.') ? host.slice(4) : host;
}
for (const r of results) {
  const url = r && r.url ? String(r.url).trim() : '';
  if (!url || !r.title) { rejected.push({ url: url, reason: 'missing url or title' }); continue; }
  const domain = parseHost(url);
  if (!domain) { rejected.push({ url: url, reason: 'not a valid http/https url' }); continue; }
  if ((r.score || 0) < 0.4) { rejected.push({ url: url, reason: 'low relevance score' }); continue; }
  if (seen.has(domain)) { rejected.push({ url: url, reason: 'duplicate publisher' }); continue; }
  const content = String(r.content || '').trim();
  if (content.length < 150) { rejected.push({ url: url, reason: 'too little content to support claims' }); continue; }
  seen.add(domain);
  valid.push({
    title: String(r.title),
    url: url,
    publisher: domain,
    published_date: r.published_date || '',
    has_published_date: Boolean(r.published_date),
    score: r.score,
    retrieved_at: retrievedAt,
    excerpt: content.slice(0, 700)
  });
  if (valid.length >= 5) break;
}
const brief = valid.map((x, i) => '[' + (i + 1) + '] ' + x.title + ' (' + x.publisher + (x.published_date ? ', ' + x.published_date : ', date unknown') + ')' + NL + x.excerpt).join(NL + NL);
return { json: Object.assign({}, t, {
  sources: valid,
  source_count: valid.length,
  rejected_sources: rejected,
  research_brief: brief,
  retrieved_at: retrievedAt,
  failure_kind: valid.length < 3 ? 'insufficient_research' : '',
  error_summary: valid.length < 3 ? 'Only ' + valid.length + ' sources passed validation (minimum 3); ' + rejected.length + ' rejected' : ''
}) };

