parameters.jsCode:
const NL = String.fromCharCode(10);
const MAX_CHARS = 1250;
const SCORE_KEYS = ['engagement', 'reach', 'audience_relevance', 'lead_generation', 'brand_alignment', 'content_quality', 'cta_effectiveness'];
const RISKS = ['Low', 'Medium', 'High', 'Critical'];
function norm(x) { return String(x || '').toLowerCase().split(NL).join(' ').split(' ').filter(Boolean).join(' '); }
function hasDeva(x) { const str = String(x || ''); for (let k = 0; k < str.length; k++) { const c = str.charCodeAt(k); if (c >= 2304 && c <= 2431) return true; } return false; }
function hasLatin(x) { const str = String(x || ''); for (let k = 0; k < str.length; k++) { const c = str.charCodeAt(k); if ((c >= 65 && c <= 90) || (c >= 97 && c <= 122)) return true; } return false; }

const t = $('Validate Sources').first().json;
const inJson = $input.first().json;
if (inJson.error) {
  return [{ json: { post_id: t.post_id, source_count: t.source_count, valid: false, failure_kind: 'service_error', errors: [], error_summary: 'AI generation error (primary and fallback): ' + String(inJson.error.message || inJson.error), risk_level: '', variation_count: 0, drafts: [] } }];
}
const o = inJson.output || {};
const sources = Array.isArray(t.sources) ? t.sources : [];
const expected = t.destination === 'Both' ? ['Personal', 'Company'] : [t.destination];
const errors = [];

if (!RISKS.includes(o.risk_level)) errors.push('risk_level missing or invalid: ' + o.risk_level);
if (!String(o.visual_recommendation || '').trim()) errors.push('visual_recommendation missing');
const vars = Array.isArray(o.variations) ? o.variations.filter(Boolean) : [];
if (vars.length !== expected.length * 3) errors.push('Expected exactly ' + (expected.length * 3) + ' variations, got ' + vars.length);

for (const dest of expected) {
  const group = vars.filter(v => v.destination === dest);
  if (group.length !== 3) errors.push(dest + ': expected exactly 3 variations, got ' + group.length);
  const nos = group.map(v => v.variation_no).sort();
  if (nos.join(',') !== '1,2,3') errors.push(dest + ': variation numbers must be 1, 2, 3 (got ' + nos.join(', ') + ')');
  for (const field of ['hook', 'angle', 'cta']) {
    const vals = group.map(v => norm(v[field]));
    if (vals.some(x => !x)) errors.push(dest + ': every variation needs a ' + field);
    else if (new Set(vals).size !== vals.length) errors.push(dest + ': each ' + field + ' must be distinct');
  }
}

const drafts = [];
for (const v of vars) {
  const label = (v.destination || '?') + ' V' + v.variation_no;
  if (!expected.includes(v.destination)) { errors.push(label + ': destination not requested for this topic'); continue; }
  const body = String(v.body || '').trim();
  if (!body) errors.push(label + ': body is empty');
  const tagList = Array.isArray(v.hashtags) ? v.hashtags.map(h => String(h).trim()).filter(Boolean) : [];
  if (tagList.length < 3 || tagList.length > 5) errors.push(label + ': needs 3-5 hashtags, got ' + tagList.length);
  const sc = v.scores || {};
  for (const k of SCORE_KEYS) {
    const x = sc[k];
    if (!Number.isInteger(x) || x < 0 || x > 100) errors.push(label + ': score ' + k + ' must be an integer 0-100');
  }
  const used = Array.isArray(v.sources_used) ? v.sources_used : [];
  if (!used.length) errors.push(label + ': no source referenced');
  if (used.some(n => !Number.isInteger(n) || n < 1 || n > sources.length)) errors.push(label + ': references a source number that does not exist');
  const textForLang = String(v.hook || '') + ' ' + body;
  if (t.language === 'English' && hasDeva(textForLang)) errors.push(label + ': English post contains Hindi script');
  if (t.language === 'Hindi' && !hasDeva(body)) errors.push(label + ': Hindi post has no Devanagari text');
  if (t.language === 'Bilingual' && !(hasDeva(body) && hasLatin(body))) errors.push(label + ': Bilingual post must contain both English and Hindi');
  const tags = tagList.map(h => h.startsWith('#') ? h : '#' + h).join(' ');
  const full = [String(v.hook || '').trim(), body, String(v.cta || '').trim(), tags].filter(Boolean).join(NL + NL);
  if (full.length > MAX_CHARS) errors.push(label + ': ' + full.length + ' characters, limit is ' + MAX_CHARS);
  const nums = SCORE_KEYS.map(k => sc[k]).filter(x => typeof x === 'number');
  const avg = nums.length ? Math.round(nums.reduce((p, q) => p + q, 0) / nums.length) : 0;
  const risk = o.risk_level;
  drafts.push({
    Post_ID: t.post_id,
    Content_ID: t.post_id + '-' + v.destination.charAt(0) + '-V' + v.variation_no,
    Version: 1,
    Destination: v.destination,
    Language: t.language,
    Topic: t.topic,
    Pillar: t.pillar,
    Variation: v.variation_no,
    Angle: v.angle || '',
    Post_Text: full,
    Char_Count: full.length,
    Within_Limit: full.length <= MAX_CHARS ? 'Yes' : 'No',
    Avg_Predicted_Score: avg,
    Scores: JSON.stringify(sc),
    Score_Notes: (v.score_explanation || '') + ' | Tips: ' + (v.improvement_tips || ''),
    Risk_Level: risk,
    Risk_Notes: o.risk_notes || '',
    Admin_Approval_Required: (risk === 'High' || risk === 'Critical') ? 'Yes' : 'No',
    Visual_Recommendation: o.visual_recommendation || 'Text-only',
    Sources_Used: used.map(n => sources[n - 1]).filter(Boolean).map(x => x.url).join(NL),
    All_Sources: sources.map((x, k) => '[' + (k + 1) + '] ' + x.url).join(NL),
    Review_Status: 'Pending Review',
    Reviewer_Decision: '',
    Reviewer_Notes: '',
    Publisher_Authorization: '',
    Admin_Approval: '',
    Generated_At: new Date().toISOString(),
    Execution_ID: $execution.id
  });
}

const ok = errors.length === 0;
return [{ json: {
  post_id: t.post_id,
  source_count: t.source_count,
  valid: ok,
  failure_kind: ok ? '' : 'draft_validation',
  errors: errors,
  error_summary: errors.slice(0, 10).join('; '),
  risk_level: o.risk_level || '',
  variation_count: vars.length,
  drafts: ok ? drafts : []
} }];

const RISKS = ['Low', 'Medium', 'High', 'Critical'];
const drafts = $('Split Out Drafts').all();
const results = $input.all();
const errors = [];
const out = [];
for (let i = 0; i < drafts.length; i++) {
  const d = drafts[i].json;
  const r = results[i] ? results[i].json : {};
  const checked = r.risk_level || r.Risk_Level || r.riskLevel;
  if (r.error || !RISKS.includes(checked)) {
    errors.push(d.Content_ID + ': independent risk check returned no valid classification' + (r.error ? ' (' + String(r.error.message || r.error) + ')' : ''));
    continue;
  }
  const finalRisk = RISKS[Math.max(RISKS.indexOf(d.Risk_Level), RISKS.indexOf(checked))];
  const checkerNotes = r.risk_notes || r.Risk_Notes || '';
  const reviewStatus = String(r.Risk_Review_Status || 'Missing');
  const eligible = (reviewStatus === 'Completed' && r.Approval_Eligible === 'Yes') ? 'Yes' : 'No';
  out.push({ json: Object.assign({}, d, {
    Risk_Level: finalRisk,
    Risk_Notes: [d.Risk_Notes, checkerNotes ? 'Independent check (' + checked + '): ' + checkerNotes : 'Independent check: ' + checked].filter(Boolean).join(' | '),
    Admin_Approval_Required: (finalRisk === 'High' || finalRisk === 'Critical' || eligible === 'No') ? 'Yes' : 'No',
    Risk_Flags: r.Risk_Flags || '',
    Risk_Hash: r.Risk_Hash || '',
    Risk_Checked_At: r.Risk_Checked_At || '',
    Risk_Review_Status: reviewStatus,
    Approval_Eligible: eligible,
    Review_Status: eligible === 'Yes' ? d.Review_Status : 'Needs Human Verification'
  }) });
}
if (errors.length || out.length !== drafts.length || drafts.length === 0) {
  return [{ json: {
    post_id: $('Current Topic').first().json.post_id,
    source_count: $('Validate Sources').first().json.source_count,
    failure_kind: 'risk_check_failed',
    errors: errors,
    error_summary: errors.length ? errors.slice(0, 6).join('; ') : 'No drafts reached the risk check'
  } }];
}
return out;

const RISKS = ['Low', 'Medium', 'High', 'Critical'];
const drafts = $('Apply Risk Classification').all().map(x => x.json);
const results = $input.all().map(x => x.json);
const errors = [];
if (results.length !== drafts.length) errors.push('Database returned ' + results.length + ' responses for ' + drafts.length + ' drafts');
for (let i = 0; i < drafts.length; i++) {
  const r = results[i];
  const id = drafts[i].Content_ID;
  if (!r) { errors.push(id + ': no response from database'); continue; }
  if (r.error) { errors.push(id + ': ' + String(r.error.message || JSON.stringify(r.error))); continue; }
  if (r.success !== true) errors.push(id + ': database did not confirm the write (expected success: true)');
}
const maxRisk = drafts.reduce((m, d) => RISKS.indexOf(d.Risk_Level) > RISKS.indexOf(m) ? d.Risk_Level : m, 'Low');
const needsVerification = drafts.some(d => d.Approval_Eligible !== 'Yes');
const ok = errors.length === 0 && drafts.length > 0;
return [{ json: {
  post_id: $('Current Topic').first().json.post_id,
  source_count: $('Validate Sources').first().json.source_count,
  valid: ok,
  failure_kind: ok ? '' : 'persistence_error',
  errors: errors,
  error_summary: errors.slice(0, 6).join('; '),
  max_risk: maxRisk,
  admin_required: maxRisk === 'High' || maxRisk === 'Critical' || needsVerification,
  needs_verification: needsVerification,
  topic_status: needsVerification ? 'Needs Human Verification' : ((maxRisk === 'High' || maxRisk === 'Critical') ? 'Awaiting Review (Admin approval required)' : 'Awaiting Review'),
  content_ids: drafts.map(d => d.Content_ID),
  drafts: ok ? drafts : []
} }];

