parameters.jsCode:
const t = $('Current Topic').first().json;
const src = $input.first().json;
const attempt = Number(t.research_attempt) || 1;
const kind = src.failure_kind || (src.input_errors ? 'invalid_input' : (src.error ? 'service_error' : 'unknown'));
let detail = src.error_summary || src.input_errors || '';
if (!detail && src.error) detail = String(src.error.message || src.error.description || src.error);
if (!detail) detail = 'Unknown failure';
let status = 'Failed - Needs Operator';
let guidance = 'Check the DB Gateway and Risk Check workflows and the execution log, then set Status to Retry Research.';
if (kind === 'invalid_input') {
  status = 'Invalid Input';
  guidance = 'Fix the fields listed above in the Topic Queue row, then set Status to Retry Research.';
} else if (kind === 'insufficient_research') {
  status = attempt >= 3 ? 'Research Failed' : 'Needs Research';
  guidance = attempt >= 3 ? 'Reword the topic or add notes with angles/keywords, then set Status to Retry Research.' : 'Automatic retry with a wider search in about 6 hours. To retry sooner, add notes and set Status to Retry Research.';
} else if (kind === 'service_error') {
  status = attempt >= 3 ? 'Failed - Needs Operator' : 'Service Error';
  guidance = attempt >= 3 ? 'An external service failed on 3 attempts. Check credentials and service status, then set Status to Retry Research.' : 'A service call failed (not a content problem). Automatic retry in about 30 minutes.';
} else if (kind === 'draft_validation') {
  status = 'Draft Validation Failed';
  guidance = 'The AI drafts broke content rules and were not queued. Adjust the notes if useful, then set Status to Retry Research.';
}
return [{ json: {
  row_number: t.row_number,
  post_id: t.post_id,
  topic: t.topic,
  destination: t.destination,
  language: t.language,
  research_attempt: kind === 'invalid_input' ? Math.max(attempt - 1, 0) : attempt,
  old_status: t.status || 'New',
  failure_kind: kind,
  new_status: status,
  error_summary: detail.slice(0, 900),
  source_count: src.source_count === undefined ? '' : src.source_count,
  operator_guidance: guidance,
  failed_at: new Date().toISOString()
} }];

